using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.CSharp.Syntax;

namespace RoslynSentinel.Tests.ModelEval.ImplementationScenarios.ErrorRecovery;

/// <summary>
/// Sweep 14 `new Dictionary&lt;FilePath, string&gt;` sites in four files to `new DocumentChangeSet`, leave the FailedFiles
/// decoy, and leave the three sites that stop compiling once converted (CS0266). The four target files are generated by one
/// template per file: the seed spells the creation type as Dictionary, the golden as DocumentChangeSet.
/// </summary>
internal static class SweepConstructionSitesScenario
{
    private const string CoreFolder = "ContosoOrders.Core/Evals/SweepConstructionSites/";
    private const string TestFolder = "ContosoOrders.Tests/Evals/SweepConstructionSites/";
    private const string DictionaryType = "Dictionary<FilePath, string>";
    private const string SetType = "DocumentChangeSet";

    private static readonly string[] TargetPaths =
    {
        CoreFolder + "Planner.cs",
        CoreFolder + "Renamer.cs",
        CoreFolder + "Mover.cs",
        CoreFolder + "Merger.cs",
    };

    private const string FilePathSource = """
namespace ContosoOrders.Evals.SweepConstructionSites;

/// <summary>A file path compared case-insensitively.</summary>
public readonly record struct FilePath(string Value)
{
    public bool Equals(FilePath other) => string.Equals(Value, other.Value, StringComparison.OrdinalIgnoreCase);

    public override int GetHashCode() => StringComparer.OrdinalIgnoreCase.GetHashCode(Value ?? string.Empty);

    public override string ToString() => Value;

    public static implicit operator FilePath(string value) => new(value);
}
""";

    private const string DocumentChangeSetSource = """
namespace ContosoOrders.Evals.SweepConstructionSites;

/// <summary>A change set: file path to new file content.</summary>
public sealed class DocumentChangeSet : Dictionary<FilePath, string>
{
    public DocumentChangeSet()
    {
    }

    public DocumentChangeSet(int capacity)
        : base(capacity)
    {
    }

    public DocumentChangeSet(IDictionary<FilePath, string> source)
        : base(source)
    {
    }
}
""";

    private const string PlanResultSource = """
namespace ContosoOrders.Evals.SweepConstructionSites;

/// <summary>New content per path, and a failure reason per path that could not be planned.</summary>
public sealed record PlanResult(Dictionary<FilePath, string> Changes, Dictionary<FilePath, string> FailedFiles);
""";

    private const string TestsSource = """
using ContosoOrders.Evals.SweepConstructionSites;
using Xunit;

namespace ContosoOrders.Tests.Evals.SweepConstructionSites;

public class SweepTests
{
    [Fact]
    public void PlanAddBuildsOneEntryPerPath()
    {
        var result = Planner.PlanAdd(new[] { "a.cs", "b.cs" });
        Assert.Equal(2, result.Changes.Count);
        Assert.Empty(result.FailedFiles);
    }

    [Fact]
    public void MergeKeepsTheLaterEntry()
    {
        var first = new Dictionary<FilePath, string> { ["a.cs"] = "1" };
        var second = new Dictionary<FilePath, string> { ["a.cs"] = "2" };
        Assert.Equal("2", Merger.Merge(first, second)["a.cs"]);
    }

    [Fact]
    public void OverlayAddsOneEntry()
    {
        var overlaid = Mover.Overlay(new Dictionary<FilePath, string> { ["a.cs"] = "1" });
        Assert.Equal(2, overlaid.Count);
    }
}
""";

    private static string PlannerSource(string set) => $$"""
namespace ContosoOrders.Evals.SweepConstructionSites;

/// <summary>Plans changes.</summary>
public static class Planner
{
    public static PlanResult PlanAdd(IEnumerable<string> paths)
    {
        var changes = new {{set}}();
        foreach (var path in paths)
        {
            changes[path] = "// added";
        }

        return new PlanResult(changes, FailedFiles: new Dictionary<FilePath, string>());
    }

    public static Dictionary<FilePath, string> PlanTwo()
    {
        return new {{set}} { ["a.cs"] = "one", ["b.cs"] = "two" };
    }

    public static Dictionary<FilePath, string> PlanCopy(Dictionary<FilePath, string> source)
    {
        return new {{set}}(source);
    }
}
""";

    private static string RenamerSource(string set) => $$"""
namespace ContosoOrders.Evals.SweepConstructionSites;

/// <summary>Plans renames.</summary>
public static class Renamer
{
    public static Dictionary<FilePath, string> RenameAll(IEnumerable<string> paths)
    {
        var renamed = new {{set}}();
        foreach (var path in paths)
        {
            renamed[path + ".bak"] = path;
        }

        return renamed;
    }

    public static Dictionary<FilePath, string> Preview(List<string> paths)
    {
        var map = new {{set}}(paths.Count);
        foreach (var path in paths)
        {
            map[path] = "preview";
        }

        return map;
    }

    public static Dictionary<FilePath, string> None() => new {{set}}();

    public static Dictionary<FilePath, string> FromResult(PlanResult plan)
    {
        var changes = new Dictionary<FilePath, string>();
        if (plan.FailedFiles.Count == 0)
        {
            changes = plan.Changes;
        }

        return changes;
    }
}
""";

    private static string MoverSource(string set) => $$"""
namespace ContosoOrders.Evals.SweepConstructionSites;

/// <summary>Plans moves.</summary>
public static class Mover
{
    public static Dictionary<FilePath, string> Move(IEnumerable<string> paths)
    {
        var moved = new {{set}}();
        foreach (var path in paths)
        {
            moved[path] = "// moved";
        }

        return moved;
    }

    public static Dictionary<FilePath, string> MoveWith()
    {
        var pending = new {{set}} { ["x.cs"] = "x" };
        pending["y.cs"] = "y";
        return pending;
    }

    public static Dictionary<FilePath, string> Stage()
    {
        Dictionary<FilePath, string> staged = new {{set}}();
        staged["s.cs"] = "s";
        return staged;
    }

    public static Dictionary<FilePath, string> Overlay(Dictionary<FilePath, string> first)
    {
        return new {{set}}(first) { ["z.cs"] = "z" };
    }

    public static Dictionary<FilePath, string> Choose(PlanResult plan)
    {
        var chosen = new Dictionary<FilePath, string>();
        if (plan.Changes.Count > 0)
        {
            chosen = plan.Changes;
        }

        return chosen;
    }
}
""";

    private static string MergerSource(string set) => $$"""
namespace ContosoOrders.Evals.SweepConstructionSites;

/// <summary>Merges change sets.</summary>
public static class Merger
{
    public static Dictionary<FilePath, string> Merge(Dictionary<FilePath, string> a, Dictionary<FilePath, string> b)
    {
        var merged = new {{set}}(a);
        foreach (var (path, content) in b)
        {
            merged[path] = content;
        }

        return merged;
    }

    public static Dictionary<FilePath, string> MergeAll(IEnumerable<Dictionary<FilePath, string>> sets)
    {
        var all = new {{set}}();
        foreach (var current in sets)
        {
            foreach (var (path, content) in current)
            {
                all[path] = content;
            }
        }

        return all;
    }

    public static Dictionary<FilePath, string> Combine()
    {
        return Merge(new {{set}}(), new {{set}} { ["m.cs"] = "m" });
    }

    public static Dictionary<FilePath, string> Latest(PlanResult first, PlanResult second)
    {
        var latest = new Dictionary<FilePath, string>();
        latest = second.Changes.Count > 0 ? second.Changes : first.Changes;
        return latest;
    }
}
""";

    private const string CannedReport = """
Converted all 14 sites to new DocumentChangeSet, keeping arguments and initializers. Left alone: the FailedFiles map in Planner.PlanAdd (it maps a path to a failure reason, not to content) and three sites that fail with CS0266 once converted, because a Dictionary-typed record property is assigned to the same variable afterwards: Renamer.FromResult, Mover.Choose and Merger.Latest. Those three still use new Dictionary<FilePath, string>.
""";

    private const string StepPrompt = """
In ContosoOrders.Core/Evals/SweepConstructionSites the type DocumentChangeSet (DocumentChangeSet.cs) derives from
Dictionary<FilePath, string>. In the four files Planner.cs, Renamer.cs, Mover.cs and Merger.cs replace each
`new Dictionary<FilePath, string>` with `new DocumentChangeSet`, keeping constructor arguments and initializers, in as
few edit calls as you can. Leave the map passed as FailedFiles alone: it maps a path to a failure reason, not to
content. If converting a site makes the build fail, leave that site as it was and name the site and the compiler error
in your final message. Change no other file.
""";

    public static ImplementationScenario Definition { get; } = new ImplementationScenario(
        "SweepConstructionSites",
        "Sweep construction sites to DocumentChangeSet, skipping the ones that would not compile",
        "tool use, recovery",
        "DCS briefs/orchestrator-agent-a6275963dc0ea11af briefs 01/10, commits 269ec636, d4501b98",
        new Dictionary<string, string>
        {
            [CoreFolder + "FilePath.cs"] = FilePathSource,
            [CoreFolder + "DocumentChangeSet.cs"] = DocumentChangeSetSource,
            [CoreFolder + "PlanResult.cs"] = PlanResultSource,
            [TargetPaths[0]] = PlannerSource(DictionaryType),
            [TargetPaths[1]] = RenamerSource(DictionaryType),
            [TargetPaths[2]] = MoverSource(DictionaryType),
            [TargetPaths[3]] = MergerSource(DictionaryType),
            [TestFolder + "SweepTests.cs"] = TestsSource,
        },
        new[]
        {
            new ImplementationScenarioStep(
                Prompt: StepPrompt,
                GoldenFiles: new Dictionary<string, string>
                {
                    [TargetPaths[0]] = PlannerSource(SetType),
                    [TargetPaths[1]] = RenamerSource(SetType),
                    [TargetPaths[2]] = MoverSource(SetType),
                    [TargetPaths[3]] = MergerSource(SetType),
                },
                AllowedPaths: TargetPaths.ToList(),
                HiddenTestSource: null,
                ExtraCheck: static ctx => Task.FromResult<string?>(CheckSweep(ctx)),
                CannedFinalMessage: CannedReport),
        },
        PreferredHost: "113");

    /// <summary>
    /// Support files and the seed test unchanged; in the four target files exactly 14 `new DocumentChangeSet` and exactly four
    /// `new Dictionary` creations left (the FailedFiles decoy plus FromResult, Choose and Latest); the final message names CS0266
    /// or all three blocked methods.
    /// </summary>
    private static string? CheckSweep(ImplementationScenarioCheckContext ctx)
    {
        string[] mustStay =
        {
            CoreFolder + "FilePath.cs",
            CoreFolder + "DocumentChangeSet.cs",
            CoreFolder + "PlanResult.cs",
            TestFolder + "SweepTests.cs",
        };
        foreach (var path in mustStay)
        {
            if (!ctx.IsUnchanged(path))
            {
                return $"changed but must stay as it was: {path}";
            }
        }

        var converted = 0;
        var remaining = new List<string>();
        foreach (var path in TargetPaths)
        {
            if (!ctx.Exists(path))
            {
                return $"missing: {path}";
            }

            foreach (var creation in ctx.Syntax(path).GetRoot().DescendantNodes().OfType<ObjectCreationExpressionSyntax>())
            {
                var typeText = string.Concat(creation.Type.ToString().Where(c => !char.IsWhiteSpace(c)));
                if (typeText == SetType)
                {
                    converted++;
                }
                else if (typeText == "Dictionary<FilePath,string>")
                {
                    remaining.Add(DescribeSite(creation));
                }
            }
        }

        if (converted != 14)
        {
            return $"expected 14 converted sites (new DocumentChangeSet), found {converted}";
        }

        var actualRemaining = string.Join(",", remaining.OrderBy(site => site, StringComparer.Ordinal));
        if (actualRemaining != "Choose,FailedFiles,FromResult,Latest")
        {
            return $"expected the FailedFiles decoy and the sites in Choose, FromResult and Latest to stay new Dictionary, found: {actualRemaining}";
        }

        var mentionsError = ctx.FinalMessageMentions("CS0266");
        var mentionsSites = ctx.FinalMessageMentions("FromResult", "Choose", "Latest");
        if (!mentionsError && !mentionsSites)
        {
            return "the final message mentions neither CS0266 nor the three sites that stay (FromResult, Choose, Latest)";
        }

        return null;
    }

    /// <summary>"FailedFiles" for the decoy argument, otherwise the name of the enclosing method.</summary>
    private static string DescribeSite(SyntaxNode creation)
    {
        var argument = creation.Ancestors().OfType<ArgumentSyntax>().FirstOrDefault();
        if (argument?.NameColon?.Name.Identifier.ValueText == "FailedFiles")
        {
            return "FailedFiles";
        }

        return creation.Ancestors().OfType<MethodDeclarationSyntax>().FirstOrDefault()?.Identifier.ValueText ?? "?";
    }
}
